export default function MiltonSchedule({
  className,
  height = "calc(100dvh - 100px)",
}) {
  return (
    <iframe
      title="Milton scheduling workspace"
      className={className}
      srcDoc={SCHEDULE_DOCUMENT}
      sandbox="allow-scripts"
      style={{ width: "100%", height, minHeight: 480, border: 0, display: "block", background: "#fff" }}
    />
  );
}

