const SCHEDULE_ENGINE = [
  "(function(root){",
  "  const DAY=86400000;",
  "  const date=s=>new Date(s+'T12:00:00Z');",
  "  const iso=d=>d.toISOString().slice(0,10);",
  "  const add=(s,n)=>iso(new Date(date(s).getTime()+n*DAY));",
  "  const diff=(a,b)=>Math.round((date(a)-date(b))/DAY);",
  "  const weekday=s=>date(s).getUTCDay();",
  "  const clone=x=>JSON.parse(JSON.stringify(x));",
  "  let seq=0;",
  "  const uid=()=> 'event-'+Date.now().toString(36)+'-'+(++seq);",
  "  function occurrences(state,from,to){",
  "    const out=[];",
  "    for(const rule of state.rules){",
  "      for(let d=from;d<=to;d=add(d,1)){",
  "        if(d<rule.date||d>(rule.until||'9999-12-31'))continue;",
  "        if(rule.repeat?weekday(d)!==weekday(rule.date):d!==rule.date)continue;",
  "        const key=rule.id+'@'+d;",
  "        if(state.exceptions[key])continue;",
  "        out.push({...clone(rule),key,ruleId:rule.id,originDate:d,date:d,roster:clone(state.rosters[key]||rule.roster||[])});",
  "      }",
  "    }",
  "    for(const [key,v] of Object.entries(state.exceptions)){",
  "      if(!v.deleted&&v.date>=from&&v.date<=to)out.push({...clone(v),key,roster:clone(state.rosters[key]||v.roster||[])});",
  "    }",
  "    return out.sort((a,b)=>a.date.localeCompare(b.date)||a.start-b.start);",
  "  }",
  "  function validate(e){",
  "    if(!e.title?.trim())throw Error('Add a title.');",
  "    if(!/^\\d{4}-\\d{2}-\\d{2}$/.test(e.date)||Number.isNaN(date(e.date).getTime()))throw Error('Choose a valid date.');",
  "    if(!Number.isInteger(e.start)||e.start<360||e.start>=1200||!Number.isInteger(e.duration)||e.duration<15||e.start+e.duration>1200)throw Error('Choose a session between 6 AM and 8 PM, at least 15 minutes long.');",
  "    if(e.until&&e.until<e.date)throw Error('End date must be on or after the first session.');",
  "    if(!Number.isInteger(e.capacity)||e.capacity<1||e.capacity>50)throw Error('Capacity must be 1–50.');",
  "    if(e.type==='one'&&e.capacity!==1)throw Error('A 1:1 session has one client.');",
  "    if(e.type==='room'&&!e.room)throw Error('Choose a room.');",
  "    if(e.type==='meeting'&&!e.staff?.length)throw Error('Choose at least one team member.');",
  "    if((e.type==='class'||e.type==='one')&&!e.coach)throw Error('Assign a coach.');",
  "    if((e.roster||[]).filter(x=>x.status!=='waitlist').length>e.capacity)throw Error('Capacity cannot be below the number booked.');",
  "  }",
  "  function resources(e){return [...new Set([e.coach,...(e.staff||[]),...(e.type==='block'?(e.staff||[]):[])].filter(Boolean))]}",
  "  function clashes(list){",
  "    const out=[];",
  "    for(let i=0;i<list.length;i++)for(let j=i+1;j<list.length;j++){",
  "      const a=list[i],b=list[j];if(a.date!==b.date||a.start>=b.start+b.duration||b.start>=a.start+a.duration)continue;",
  "      const reasons=[];const staff=resources(a).filter(x=>resources(b).includes(x));if(staff.length)reasons.push('staff: '+staff.join(', '));",
  "      if(a.room&&a.room===b.room)reasons.push('room: '+a.room);",
  "      const booked=e=>(e.roster||[]).filter(x=>x.status!=='waitlist').map(x=>x.member);",
  "      if(booked(a).some(x=>booked(b).includes(x)))reasons.push('client is already booked');",
  "      if(reasons.length)out.push({a:a.key,b:b.key,date:a.date,message:a.title+' / '+b.title+' — '+reasons.join('; ')});",
  "    }return out;",
  "  }",
  "  function stage(state,occ,patch,scope='single',deleting=false){",
  "    const next=clone(state);let focus=null;",
  "    if(!occ){const e={...patch,id:uid()};validate(e);next.rules.push(e);focus=e.id+'@'+e.date;return {state:next,focus};}",
  "    const rule=next.rules.find(r=>r.id===occ.ruleId);if(!rule)throw Error('Session no longer exists.');",
  "    if(scope==='single'||!rule.repeat){",
  "      if(deleting)next.exceptions[occ.key]={deleted:true};",
  "      else {const e={...occ,...patch,key:occ.key};validate(e);next.exceptions[occ.key]=e;focus=occ.key;}",
  "    }else{",
  "      const shift=patch.date?diff(patch.date,occ.date):0;",
  "      const oldUntil=rule.until;",
  "      if(scope==='future')rule.until=add(occ.originDate,-1);",
  "      else next.rules=next.rules.filter(r=>r.id!==rule.id);",
  "      let replacement;",
  "      if(!deleting){",
  "        replacement={...rule,...patch,id:uid(),date:add(scope==='future'?occ.originDate:rule.date,shift),until:patch.until??oldUntil,roster:clone(rule.roster||[])};",
  "        validate(replacement);next.rules.push(replacement);focus=replacement.id+'@'+add(occ.originDate,shift);",
  "      }",
  "      for(const key of new Set([...Object.keys(next.exceptions),...Object.keys(next.rosters)])){",
  "        if(!key.startsWith(rule.id+'@'))continue;const d=key.split('@')[1];if(scope==='future'&&d<occ.originDate)continue;",
  "        if(replacement){const nk=replacement.id+'@'+add(d,shift);if(next.rosters[key])next.rosters[nk]=next.rosters[key];if(next.exceptions[key]?.deleted)next.exceptions[nk]={deleted:true};}",
  "        delete next.exceptions[key];delete next.rosters[key];",
  "      }",
  "    }",
  "    return {state:next,focus};",
  "  }",
  "  function newConflicts(before,after,from,to){",
  "    const old=clashes(occurrences(before,from,to));",
  "    const seen=new Set(old.map(x=>x.date+'|'+x.message));",
  "    return clashes(occurrences(after,from,to)).filter(x=>!seen.has(x.date+'|'+x.message));",
  "  }",
  "  const api={date,iso,add,diff,weekday,clone,uid,occurrences,validate,resources,clashes,stage,newConflicts};",
  "  root.ScheduleEngine=api;if(typeof module!=='undefined')module.exports=api;",
  "})(typeof window==='undefined'?globalThis:window);",
  ""
].join("\n");
