  "register({name:'create_schedule_session',description:'Create one non-recurring class with conflict validation in the demo only.',inputSchema:{type:'object',properties:{service:{type:'string'},date:{type:'string'},hour:{type:'integer',minimum:6,maximum:19},minute:{type:'integer',minimum:0,maximum:59},coach:{type:'string'},capacity:{type:'integer',minimum:1,maximum:50},location:{type:'string'}},required:['service','date','hour','coach','capacity','location'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!coaches.includes(input.coach)||!rooms.includes(input.location))throw Error('Unknown staff or room');const svc=services.find(s=>s.name===input.service);if(!svc)throw Error('Unknown service');const p={title:svc.name,type:svc.type,date:input.date,start:input.hour*60+(input.minute||0),duration:svc.duration,coach:input.coach,room:input.location,capacity:input.capacity,roster:[],staff:[],repeat:false,visibility:'members',service:svc.id};const out=E.stage(state,null,p);checkAndApply(out.state,out.focus,p.date,'Booking created',p.title);return{id:out.focus,status:'created'}}});",
